    const house = housesById.get(household.houseId);
    if (!house) continue;
    const homeRoad = homeRoadForCitizen(world, house);
    if (!homeRoad) continue;
    const citizen: CitizenView = {
      id: household.houseId,
      houseId: household.houseId,
      workplaceId: null,
      x: homeRoad.x,
      y: homeRoad.y,
      state: "strolling",
      dwellTicks: 0,
    };
