      nextCitySentiment(50, {
        taxRate: "high",
        wageLevel: "high",
        households: 4,
        hungryHouseholds: 0,
      }),
    ).toEqual({ value: 50, reasons: ["重税 -2", "优厚工资 +1", "饱腹 +1"] });
  });

  it("轻税、常薪与饱腹提升民心，低薪和缺粮会加剧不满", () => {
    expect(
      nextCitySentiment(40, {
        taxRate: "low",
        wageLevel: "standard",
        households: 2,
        hungryHouseholds: 0,
      }).value,
    ).toBe(42);
    expect(
      nextCitySentiment(40, {
